def F(g):
    h=len(g); w=len(g[0])
    C=collections.Counter(v for r in g for v in r).most_common(1)[0][0]
    o=[[C]*w for _ in range(h)]
    for j in range(w):
        vals=[g[i][j] for i in range(h) if g[i][j]!=C]
        for i in range(len(vals)): o[h-len(vals)+i][j]=vals[i]
    return o
